program='''from collections import deque, Counter


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            pts = []
            for x, y in q:
                pts.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            out.append((color, frozenset(pts)))
    return out


def _variants(points):
    # Congruence under rotation and reflection.
    variants = []
    for reflect in (False, True):
        for rot in range(4):
            p = []
            for x, y in points:
                if reflect:
                    y = -y
                for _ in range(rot):
                    x, y = y, -x
                p.append((x, y))
            x0 = min(x for x, y in p)
            y0 = min(y for x, y in p)
            variants.append(frozenset((x-x0, y-y0) for x, y in p))
    return set(variants)


def _box(points):
    return (min(x for x,y in points), max(x for x,y in points),
            min(y for x,y in points), max(y for x,y in points))


def _disjoint(a, b):
    return a[1] < b[0] or b[1] < a[0] or a[3] < b[2] or b[3] < a[2]


def _fits_in_pixels(shape, pixels):
    # True if any rotation/reflection and translation of shape is contained in pixels.
    for shape in _variants(shape):
        mh = max(x for x,y in shape) + 1
        mw = max(y for x,y in shape) + 1
        for x0 in range(min(x for x,y in pixels), max(x for x,y in pixels)-mh+2):
            for y0 in range(min(y for x,y in pixels), max(y for x,y in pixels)-mw+2):
                if all((x0+x,y0+y) in pixels for x,y in shape):
                    return True
    return False


def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    objects = _components(g, bg)
    boxes = [_box(p) for _, p in objects]
    sigs = [_variants(p) for _, p in objects]
    candidates = []

    # A larger, differently-shaped component contains a smaller exemplar in its box.
    # A matching copy outside that box takes the containing component's color.
    for ki, (key_color, key) in enumerate(objects):
        key_box = boxes[ki]
        for ti, (target_color, target) in enumerate(objects):
            if ti == ki or not _disjoint(key_box, boxes[ti]):
                continue
            target_sig = sigs[ti]
            if target_sig.intersection(sigs[ki]):
                continue
            # Prefer a complete, separate object inside the key's bounding box.
            for ii, (inner_color, inner) in enumerate(objects):
                if ii == ki or ii == ti or not all(key_box[0] <= x <= key_box[1] and key_box[2] <= y <= key_box[3] for x,y in inner):
                    continue
                if target_sig.intersection(sigs[ii]):
                    candidates.append((len(inner), len(key), key_color, target, "object"))
                    break
            else:
                # Some examples use a motif made directly by a subset of the key object.
                if _fits_in_pixels(target, key):
                    candidates.append((0, len(key), key_color, target, "subset"))

    if candidates:
        # The internal exemplar is the strongest signal. Resolve ties by the largest exemplar.
        best = max(candidates, key=lambda x: (x[0], x[1]))
        color, target = best[2], best[3]
        for r, c in target:
            g[r][c] = color
    return g
'''
